//! yapocis for Rust.
//!
//! Call the yapocis image-processing kernels (OpenCL, Metal, CUDA) from Rust
//! with no Python at runtime. The kernel sources and their signatures come from
//! a bundle generated by the Python package (`yapocis-tools bundle`) and
//! vendored in this crate; [`interfaces`] holds one generated struct per
//! interface with a typed method per kernel, and [`lib`] ports the thin
//! Python library wrappers.
//!
//! ```no_run
//! use yapocis::{Device, interfaces::demo::Demo};
//! use ndarray::Array1;
//!
//! let device = Device::default()?;
//! let demo = Demo::load(&device)?;
//! let a = Array1::<f32>::from_vec(vec![1.0, 2.0, 3.0]).into_dyn();
//! let b = Array1::<f32>::from_vec(vec![10.0, 20.0, 30.0]).into_dyn();
//! let c = demo.sum(&a.view(), &b.view())?;
//! assert_eq!(c.as_slice().unwrap(), &[11.0, 22.0, 33.0]);
//! # Ok::<(), yapocis::Error>(())
//! ```
//!
//! Backends are Cargo features: `ocl`, `metal` (macOS) and `cuda`. Device
//! selection honours `YAPOCIS_BACKEND` and `YAPOCIS_DEVICE` like the Python
//! package.

pub mod fonts;
pub mod host;
pub mod interfaces;
#[path = "lib/mod.rs"]
pub mod lib;

pub use yapocis_rt as rt;
pub use yapocis_rt::{
    available_backends, Backend, Buffer, CallOptions, DType, Device, Manifest, Program,
};

use std::sync::LazyLock;

/// The bundled manifest, parsed once.
pub static MANIFEST: LazyLock<Manifest> = LazyLock::new(|| {
    Manifest::from_json(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/bundle/manifest.json"
    )))
    .expect("the vendored manifest is valid")
});

/// Version of the Python yapocis package that generated the vendored bundle.
pub const BUNDLE_VERSION: &str = env!("YAPOCIS_BUNDLE_VERSION");

#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error(transparent)]
    Rt(#[from] yapocis_rt::Error),
    #[error("array argument must be C-contiguous (use as_standard_layout())")]
    NotContiguous,
    #[error("backend {0:?} is not available")]
    BackendUnavailable(Backend),
    #[error("parameter {0:?} is not an out_like output")]
    NotAnOutLike(String),
    #[error("expected {expected} out_like outputs, got {got}")]
    OutputCount { expected: usize, got: usize },
    #[error("{0}")]
    Shape(#[from] ndarray::ShapeError),
    #[error("{0}")]
    Invalid(String),
}

pub type Result<T> = std::result::Result<T, Error>;
